package app.ccswitch.android;
import org.junit.Test;
import static org.junit.Assert.*;
import org.json.*;
public class HistoryFilterTest {
 @Test public void preservesEffortToolPairsAndNestedIds()throws Exception{JSONObject input=new JSONObject("{\"reasoning\":{\"effort\":\"high\"},\"include\":[\"reasoning.encrypted_content\",\"other\"],\"input\":[{\"type\":\"reasoning\",\"id\":\"rs_old\",\"encrypted_content\":\"opaque\"},{\"type\":\"function_call\",\"id\":\"fc_old\",\"call_id\":\"call_a\",\"arguments\":\"{}\"},{\"type\":\"function_call_output\",\"id\":\"fco_old\",\"call_id\":\"call_a\",\"output\":\"ok\"},{\"role\":\"user\",\"id\":\"msg_old\",\"content\":[{\"file_id\":\"file_keep\"}]}]}");String before=input.toString();var r=HistoryFilter.filter(input);assertEquals(1,r.reasoning());assertEquals(3,r.ids());assertEquals(before,input.toString());assertFalse(r.body().getBoolean("store"));assertEquals("high",r.body().getJSONObject("reasoning").getString("effort"));assertEquals("call_a",r.body().getJSONArray("input").getJSONObject(0).getString("call_id"));assertEquals("file_keep",r.body().getJSONArray("input").getJSONObject(2).getJSONArray("content").getJSONObject(0).getString("file_id"));var again=HistoryFilter.filter(r.body());assertEquals(0,again.reasoning());assertEquals(0,again.ids());assertEquals(r.body().toString(),again.body().toString());}
 @Test public void rejectsUnsafeContext()throws Exception{for(String raw:new String[]{"{\"previous_response_id\":\"r\"}","{\"conversation\":{}}","{\"input\":[{\"type\":\"compaction\"}]}","{\"input\":[{\"type\":\"item_reference\",\"id\":\"x\"}]}","{\"input\":[{\"type\":\"message\",\"encrypted_content\":\"x\"}]}","{\"context_management\":[{\"type\":\"compaction\"}]}"}){try{HistoryFilter.filter(new JSONObject(raw));fail(raw);}catch(HistoryFilter.Failure expected){assertEquals(409,expected.status);}}}
 @Test public void unknownResourcesKeepIds()throws Exception{var r=HistoryFilter.filter(new JSONObject("{\"input\":[{\"type\":\"computer_call\",\"id\":\"keep\"}]}"));assertEquals("keep",r.body().getJSONArray("input").getJSONObject(0).getString("id"));}
 @Test public void validatesInputShapes()throws Exception{for(String raw:new String[]{"{\"include\":null}","{\"include\":\"bad\"}","{\"input\":null}","{\"input\":{}}"})try{HistoryFilter.filter(new JSONObject(raw));fail();}catch(HistoryFilter.Failure e){assertEquals(400,e.status);}}
}
